:18px}.progress-remaining{text-align:center;margin:14px 0 0}.progress-remaining strong{font-weight:500;margin-left:10px}.progress-status{font-size:12px;color:#86758e;text-align:center;margin:6px 0 0}.wager-explanation{margin-top:12px;font-size:12px;color:#86758e}.wager-explanation summary{cursor:pointer}.wager-explanation p{margin:8px 0 0}.withdraw-message{font-size:13px;line-height:1.7;background:#fff8ee;color:#a47846;padding:12px;margin:16px 0}.error{color:#b95e71}.withdraw-message.error{background:#fff4f5}.selectable:disabled,input:disabled{opacity:.65;cursor:not-allowed}.withdraw-submit:disabled{opacity:.5;cursor:not-allowed}.destination-overlay{position:fixed;inset:0;z-index:900;background:#2226;display:flex;align-items:center;justify-content:center;padding:20px}.destination-dialog{background:white;border-radius:12px;width:100%;max-width:560px;max-height:88vh;max-height:88dvh;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:0 20px 16px;outline:none}.destination-dialog>header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eee;padding:16px 0}.destination-dialog h2{margin:0;font-size:17px;font-weight:500}.destination-dialog header button{display:grid;place-items:center;min-width:32px;min-height:32px;color:#8b8298}button:focus-visible{outline:2px solid #8156df;outline-offset:3px}@media(max-width:760px){.withdraw-row{min-height:57px;padding:16px 0;font-size:16px;gap:8px}.withdraw-row input{font-size:16px}.withdraw-row>svg:first-child{width:21px;height:21px}.withdraw-row small{font-size:11px}.withdraw-help,.withdraw-progress{font-size:13px;padding:12px 14px;margin-bottom:32px}.withdraw-help h2,.withdraw-progress h2{font-size:14px}.destination-overlay{padding:16px}.destination-dialog{padding:0 16px 12px}}@media(max-width:360px){.withdraw-row{font-size:14px;gap:6px}.withdraw-row input{font-size:16px}.withdraw-row>svg:first-child{width:18px;height:18px}.withdraw-row strong{font-size:14px}.withdr